#!/usr/bin/env python3
"""Read local data from a first-generation Clairy."""

import argparse
import datetime as dt
import json
import socket
import struct
import time

GROUP = "239.0.0.1"
PORT = 6666
GET_ID = bytes.fromhex("02 09 00 ff ff 0c 00 00 02 13 03")
# Exact packet generated by the original Android app for GET_FIRMWARE.
# It is GET_PARAMETER (0x0f), parameter id 2.
GET_FIRMWARE = bytes.fromhex("02 09 00 ff ff 0f 04 00 02 00 00 00 02 1c 03")


def decode(data: bytes, firmware_query: bool = False):
    """Decode packet types whose format has been confirmed from the original app."""
    if len(data) >= 15 and data[5] == 13:
        serial = struct.unpack_from("<I", data, 8)[0]
        return {"type": "identity", "serial": f"{serial:09d}"}

    if len(data) >= 19 and data[5] == 1:
        temperature, humidity, quality, fan, speed = struct.unpack_from(
            "<HHHBB", data, 8
        )
        return {
            "type": "reading",
            "temperature_c": temperature / 10.0,
            "humidity_percent": humidity / 10.0,
            "air_quality": quality / 10.0,
            "fan_on": bool(fan),
            "fan_speed_raw": speed,
            "received_utc": dt.datetime.now(dt.timezone.utc).isoformat(),
            "raw_hex": data.hex(),
        }

    # Original UDPListenerService dispatches opcode 0x10 as GET_PARAMETER response.
    # Bytes 8..11 are the parameter id (little-endian). Parameter 2 is firmware.
    # readFirmwareMessage() takes data[6] bytes starting at offset 12 as the string.
    if firmware_query and len(data) >= 12 and data[5] == 0x10:
        parameter_id = struct.unpack_from("<I", data, 8)[0]
        if parameter_id == 2:
            firmware_len = data[6]
            end = 12 + firmware_len
            if end <= len(data):
                firmware = data[12:end].decode("ascii", errors="replace")
                return {
                    "type": "firmware",
                    "firmware": firmware,
                    "parameter_id": parameter_id,
                    "raw_hex": data.hex(),
                }

    if len(data) >= 9 and data[5] == 0xFE:
        return {
            "type": "nack",
            "error": data[8],
            "raw_hex": data.hex(),
        }

    return None


def printable(data: bytes) -> str:
    return "".join(chr(b) if 32 <= b < 127 else "." for b in data)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--interface",
        default="0.0.0.0",
        help="IPv4 address of the LAN interface used to join multicast",
    )
    parser.add_argument("--ip", help="Known Clairy IPv4 address")
    parser.add_argument(
        "--firmware",
        action="store_true",
        help="Send the original local firmware-version query to --ip",
    )
    parser.add_argument(
        "--raw",
        action="store_true",
        help="Print packets whose format is not yet decoded",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=0,
        help="Exit after this many seconds; 0 waits forever",
    )
    args = parser.parse_args()

    if args.firmware and not args.ip:
        parser.error("--firmware requires --ip")

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    sock.bind(("", PORT))
    membership = socket.inet_aton(GROUP) + socket.inet_aton(args.interface)
    sock.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP, membership)
    sock.settimeout(1.0)

    if args.ip:
        # The original app serializes commands. Sending GET_ID and GET_FIRMWARE
        # back-to-back can make the purifier ignore the second command, so a
        # firmware query is sent by itself.
        command = GET_FIRMWARE if args.firmware else GET_ID
        sock.sendto(command, (args.ip, PORT))
        if args.firmware:
            print(
                json.dumps(
                    {
                        "type": "sent",
                        "command": "get_firmware",
                        "target": args.ip,
                        "raw_hex": GET_FIRMWARE.hex(),
                    },
                    sort_keys=True,
                ),
                flush=True,
            )

    serial = None
    started = time.monotonic()
    while True:
        if args.timeout and time.monotonic() - started >= args.timeout:
            return
        try:
            data, address = sock.recvfrom(65535)
        except socket.timeout:
            continue
        if args.ip and address[0] != args.ip:
            continue

        decoded = decode(data, firmware_query=args.firmware)
        if decoded is not None:
            decoded["source_ip"] = address[0]
            if decoded["type"] == "identity":
                serial = decoded["serial"]
            elif serial is not None:
                decoded["serial"] = serial
            print(json.dumps(decoded, sort_keys=True), flush=True)
            continue

        if args.raw:
            print(
                json.dumps(
                    {
                        "type": "raw",
                        "source_ip": address[0],
                        "opcode": data[5] if len(data) > 5 else None,
                        "length": len(data),
                        "ascii": printable(data),
                        "raw_hex": data.hex(),
                    },
                    sort_keys=True,
                ),
                flush=True,
            )


if __name__ == "__main__":
    main()
